<div class="section-heading"><h2>Match schedule</h2><a class="btn btn-dark" href="<?= url('admin-match-edit') ?>">+ Create match</a></div><section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Date / time</th><th>Opponent</th><th>Venue</th><th>Score (VMU first)</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach(query('SELECT * FROM matches ORDER BY match_date DESC,match_time DESC') as $m): ?><tr><td><?= e($m['match_date']) ?><small><?= e(substr($m['match_time'],0,5)) ?></small></td><td><a href="<?= url('match',['id'=>$m['id']]) ?>"><?= e($m['opponent_name']) ?></a></td><td><?= e($m['home_away']) ?></td><td><?= $m['status']==='Completed'?e($m['our_score'].' – '.$m['opponent_score']):'—' ?></td><td><?= badge($m['status']) ?></td><td class="action-links"><a href="<?= url('admin-match-edit',['id'=>$m['id']]) ?>">Edit</a><a href="<?= url('admin-attendance',['id'=>$m['id']]) ?>">Attendance</a><?php if($m['status']==='Completed'): ?><a href="<?= url('admin-stats',['id'=>$m['id']]) ?>">Stats</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
